 void showPackExceeded(BigDecimal pack,BigDecimal pieces){extra.setError("Quantidade excede o pack");if(packWarningOpen)return;packWarningOpen=true;lastPackWarning=item.getText().toString()+"|"+selectedUnit()+"|"+pieces.toPlainString();new AlertDialog.Builder(this).setTitle("Quantidade excede o pack").setMessage("Este produto tem "+pack.toPlainString()+" peças por "+selectedUnit()+". Você informou "+pieces.toPlainString()+" peças soltas. Ajuste a quantidade de caixas/paletes ou de peças soltas.").setPositiveButton("Corrigir",(dialog,which)->extra.requestFocus()).setOnDismissListener(d->packWarningOpen=false).show();}
 void queuePackCheck(){if(pendingPackCheck!=null)packHandler.removeCallbacks(pendingPackCheck);pendingPackCheck=()->{if(isFinishing()||isDestroyed()||"PC".equals(selectedUnit()))return;PackCatalog.Product p=findScannedPack(item.getText().toString());BigDecimal factor=p==null?null:p.factor(selectedUnit());if(factor==null)return;try{BigDecimal n=new BigDecimal(extra.getText().toString().trim().replace(',','.'));String token=item.getText().toString()+"|"+selectedUnit()+"|"+n.toPlainString();if(PackCatalog.exceedsPack(n,factor)){if(!token.equals(lastPackWarning))showPackExceeded(factor,n);}else{extra.setError(null);lastPackWarning="";}}catch(NumberFormatException e){}};packHandler.postDelayed(pendingPackCheck,600);}
