 void migratePacks(){java.util.HashSet<String> columns=new java.util.HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info(registros)",null)){while(c.moveToNext())columns.add(c.getString(c.getColumnIndexOrThrow("name")));}if(!columns.contains("pecas_extras"))db.execSQL("ALTER TABLE registros ADD COLUMN pecas_extras TEXT NOT NULL DEFAULT '0'");if(!columns.contains("pack_pc"))db.execSQL("ALTER TABLE registros ADD COLUMN pack_pc TEXT NOT NULL DEFAULT ''");if(!columns.contains("total_pc"))db.execSQL("ALTER TABLE registros ADD COLUMN total_pc TEXT NOT NULL DEFAULT ''");}
 void migrateOfflineSync(){java.util.HashSet<String> columns=new java.util.HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info(registros)",null)){while(c.moveToNext())columns.add(c.getString(c.getColumnIndexOrThrow("name")));}if(!columns.contains("sync_uuid"))db.execSQL("ALTER TABLE registros ADD COLUMN sync_uuid TEXT");if(!columns.contains("sync_status"))db.execSQL("ALTER TABLE registros ADD COLUMN sync_status TEXT NOT NULL DEFAULT 'PENDENTE'");if(!columns.contains("codigo_lido"))db.execSQL("ALTER TABLE registros ADD COLUMN codigo_lido TEXT");db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT id,item FROM registros WHERE sync_uuid IS NULL OR sync_uuid=''",null)){while(c.moveToNext()){ContentValues values=new ContentValues();values.put("sync_uuid",java.util.UUID.randomUUID().toString());values.put("codigo_lido",c.getString(1));db.update("registros",values,"id=?",new String[]{String.valueOf(c.getLong(0))});}}db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS idx_registros_sync_uuid ON registros(sync_uuid)");db.setTransactionSuccessful();}finally{db.endTransaction();}}
